def calculate_max_reward(n, s, r):
    """Calculates the maximum total reward in millions of VND for forming groups of three people.

    Args:
        n: The total number of tickets (numbered 1 to n).
        s: The target sum for each triplet (a, b, c with a < b < c).
        r: The reward per unique group.

    Returns:
        The maximum total reward rounded to the nearest integer.
    """
    count = 0
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if i + j + k == s:
                    count += 1
    return round(count * r / 1000000)

# Test cases
assert calculate_max_reward(100, 100, 50000) == 39
assert calculate_max_reward(50, 50, 20000) == 4
